<section class="portal-admin-content county-dashboard">@if($context['type']==='county')<nav class="portal-county-dashboard-actions" aria-label="مدیریت پرتال"><a class="portal-button" href="{{ $context['dashboard_path'] }}/news/new">＋ افزودن خبر</a><a href="{{ $context['dashboard_path'] }}/portal">ظاهر و اطلاعات پرتال</a><a href="{{ $context['public_path'] }}" target="_blank" rel="noopener">مشاهدهٔ سایت فرمانداری ↗</a></nav>@endif<p class="portal-admin-help">{{ $context['can_write']?'مدیریت محتوای سازمان و پیگیری خدمات مردمی':'این فضای کاری فقط برای مشاهدهٔ اطلاعات است.' }}</p><div class="county-stats-grid grid gap-4 sm:grid-cols-2 lg:grid-cols-4">@foreach(['محتوا'=>array_sum($stats['contents_by_type']??[]),'منتشرشده'=>$stats['contents_by_status']['published']??0,'گزارش‌های مردمی'=>array_sum($stats['tickets_by_status']??[]),'نیازمند پیگیری'=>$stats['overdue_tickets']??0] as $label=>$value)<article class="county-stat-card rounded-xl border border-slate-200 p-5"><span>{{ $label }}</span><strong class="block text-3xl">{{ $value }}</strong></article>@endforeach</div><h2 class="my-6 text-xl font-bold">دسترسی به بخش‌ها</h2><div class="county-module-grid grid gap-4 sm:grid-cols-2 lg:grid-cols-3">@foreach($modules as $entry)@if($entry['showInNavigation'])<a class="county-module-card rounded-xl border border-slate-200 p-4" href="{{ $entry['path'] }}"><strong>{{ $entry['title'] }}</strong><p>{{ $entry['description'] }}</p></a>@endif @endforeach</div><h2 class="my-6 text-xl font-bold">آخرین محتواها</h2>@foreach($stats['recent_contents']??[] as $item)<p class="my-3">@php($target=collect($modules)->first(fn($m)=>($m['page']['defaults']['type']??null)===$item['type']))<a href="{{ $target['path']??$ui->adminHref('/panel/admin/news',$context) }}/{{ $item['id'] }}/edit">{{ $item['title'] }}</a> — {{ $item['status'] }}</p>@endforeach</section>

<section class="portal-card my-8"><h2>فعالیت ده روز اخیر</h2><p>آبی: محتوا · سبز: درخواست‌های مردمی</p>@php($maximum=max(1,...array_map(fn($day)=>max($day['contents'],$day['tickets']),$stats['daily_activity'])))<div class="portal-activity-chart">@foreach($stats['daily_activity'] as $day)<div class="portal-activity-day"><div class="portal-activity-bars"><span style="height:{{ max(2,round($day['contents']/$maximum*125)) }}px" title="{{ $day['contents'] }} محتوا"></span><span style="height:{{ max(2,round($day['tickets']/$maximum*125)) }}px" title="{{ $day['tickets'] }} درخواست"></span></div><time>{{ $ui->date($day['date']) }}</time></div>@endforeach</div></section>
<section class="portal-card"><h2>تازه‌ترین گزارش‌های مردمی</h2>@forelse($stats['recent_reports']??[] as $report)<p><a href="{{ $ui->adminHref('/panel/admin/reports/'.$report['reference'].'/edit',$context) }}">{{ $report['subject'] }}</a></p>@empty<p>گزارشی ثبت نشده است.</p>@endforelse</section>
